import{_ as s,c as t,o as a,ag as i}from"./chunks/framework.BtwP-r-R.js";const m=JSON.parse('{"title":"Exercices bloc 3","description":"","frontmatter":{"outline":"deep"},"headers":[],"relativePath":"exercices_bloc3.md","filePath":"exercices_bloc3.md"}'),l={name:"exercices_bloc3.md"};function o(r,e,n,d,u,p){return a(),t("div",null,[...e[0]||(e[0]=[i('<h1 id="exercices-bloc-3" tabindex="-1">Exercices bloc 3 <a class="header-anchor" href="#exercices-bloc-3" aria-label="Permalink to &quot;Exercices bloc 3&quot;">​</a></h1><h2 id="semaine-12" tabindex="-1">Semaine 12 <a class="header-anchor" href="#semaine-12" aria-label="Permalink to &quot;Semaine 12&quot;">​</a></h2><details class="details custom-block"><summary>Utilisation d&#39;une base de données</summary><h3 id="utilisation-d-une-base-de-donnees" tabindex="-1">Utilisation d&#39;une base de données <a class="header-anchor" href="#utilisation-d-une-base-de-donnees" aria-label="Permalink to &quot;Utilisation d&#39;une base de données&quot;">​</a></h3><h4 id="objectifs" tabindex="-1">Objectifs <a class="header-anchor" href="#objectifs" aria-label="Permalink to &quot;Objectifs&quot;">​</a></h4><p>Mettre en pratique l’utilisation d’une base de données en C#.</p><h4 id="preparation" tabindex="-1">Préparation <a class="header-anchor" href="#preparation" aria-label="Permalink to &quot;Préparation&quot;">​</a></h4><ol><li>Téléchez le projet de départ : <a href="https://gitlab.com/420-14b-fx/contenu/-/blob/main/bloc3/cours%2023/S12E1-BD.zip" target="_blank" rel="noreferrer">S12E1-BD</a></li><li>Créer dans votre SGBD une base de données nommée <strong>livre_db</strong> et exécuter le script <strong>livres_bd.sql</strong> se trouvant dans le projet de départ pour créer les tables.</li></ol><h4 id="probleme" tabindex="-1">Problème <a class="header-anchor" href="#probleme" aria-label="Permalink to &quot;Problème&quot;">​</a></h4><ol><li>Créer une nouvelle classe nommée &quot;<strong>DAL.cs</strong>&quot; (Data Access Layer). Celle-ci doit contenir les méthodes statiques permettant la gestion des livres (<strong>CRUD</strong>) contenus dans la base de données &quot;<strong>livres_bd</strong>&quot;.</li><li>Tester les différentes méthodes de votre classe &quot;<strong>DAL.cs</strong>&quot; afin de tester l’affichage de la liste des livres, l’ajout, la modification et la suppression d’un livre.</li></ol></details><details class="details custom-block"><summary>Utilisation d&#39;une base de données avec des objets composés.</summary><h3 id="utilisation-d-une-base-de-donnees-avec-des-objets-composes" tabindex="-1">Utilisation d&#39;une base de données avec des objets composés. <a class="header-anchor" href="#utilisation-d-une-base-de-donnees-avec-des-objets-composes" aria-label="Permalink to &quot;Utilisation d&#39;une base de données avec des objets composés.&quot;">​</a></h3><h4 id="objectifs-1" tabindex="-1">Objectifs <a class="header-anchor" href="#objectifs-1" aria-label="Permalink to &quot;Objectifs&quot;">​</a></h4><p>Mettre en pratique l’utilisation d’une base de données et la composition d&#39;objet. Dans cet exercices, un livres possèdes un ou plusieurs auteurs.</p><h4 id="preparation-1" tabindex="-1">Préparation <a class="header-anchor" href="#preparation-1" aria-label="Permalink to &quot;Préparation&quot;">​</a></h4><ol><li>Téléchez le projet de départ : <a href="https://gitlab.com/420-14b-fx/contenu/-/blob/main/bloc3/cours%2024/S12E2-CompositionObjets.zip?ref_type=heads" target="_blank" rel="noreferrer">S12E2-CompositionObjets</a></li><li>Importez dans pypMyAdmin - MySql le fichier <strong>bibliotheque.sql</strong> se trouvant dans le projet de départ.</li><li>La base de données contient déjà une liste d&#39;auteurs.</li></ol><h4 id="probleme-1" tabindex="-1">Problème <a class="header-anchor" href="#probleme-1" aria-label="Permalink to &quot;Problème&quot;">​</a></h4><p>Vous devez modifier l&#39;application afin de permettre à un utilisatuer d&#39;ajouter un livre avec ses auteurs, d&#39;afficher la liste des livres ainsi que les détails d&#39;un livre sélectionné.</p><ol><li><p>Compléter la classe &quot;<strong>DAL.cs</strong>&quot; (Data Access Layer). Celle-ci doit contenir les méthodes permettant d&#39;obtenir la liste des livres sans leurs auteurs, d&#39;ajouter un livre avec ses auteurs et d&#39;obtenir un livre avec ses auteurs.</p></li><li><p>Compléter les méthodes du formulaire permettant l&#39;ajout d&#39;un livre. Vous n&#39;avez pas à faire la validation du formulaire. Assurez-vous seulement qu&#39;un livre doit avoir au moins un auteur et qu&#39;il ne peut pas y avoir 2 fois le même auteurs dans la liste des auteurs.</p></li><li><p>Compléter les méthodes du formulaire permettant l&#39;affichage de la liste des livres.</p></li><li><p>Compléter les méthode du formulaire permettant l&#39;affichage des détails d&#39;un livre sélectionné dans la liste. Lors de l&#39;affichage des détails d&#39;un livre, vous devez obtenir le livre à partir de la base de données.</p></li></ol></details><h2 id="semaine-13" tabindex="-1">Semaine 13 <a class="header-anchor" href="#semaine-13" aria-label="Permalink to &quot;Semaine 13&quot;">​</a></h2><details class="details custom-block"><summary>Exercices sur l&#39;utilisation les indexeurs</summary><h3 id="exercices-sur-l-utilisation-les-indexeurs" tabindex="-1">Exercices sur l&#39;utilisation les indexeurs <a class="header-anchor" href="#exercices-sur-l-utilisation-les-indexeurs" aria-label="Permalink to &quot;Exercices sur l&#39;utilisation les indexeurs&quot;">​</a></h3><h4 id="objectifs-2" tabindex="-1">Objectifs <a class="header-anchor" href="#objectifs-2" aria-label="Permalink to &quot;Objectifs&quot;">​</a></h4><p>Mettre en pratique la création et l&#39;utilisation d&#39;indexeur en c#</p><h4 id="preparation-2" tabindex="-1">Préparation <a class="header-anchor" href="#preparation-2" aria-label="Permalink to &quot;Préparation&quot;">​</a></h4><ol><li>Créer un projet console nommé &quot;<strong>S13E1-Indexeurs</strong>&quot;</li></ol><h4 id="probleme-2" tabindex="-1">Problème <a class="header-anchor" href="#probleme-2" aria-label="Permalink to &quot;Problème&quot;">​</a></h4><ol><li>Créer une classe Employe ayant les propriétés et méthodes suivantes :</li></ol><p><strong>Propriétés publiques</strong>:</p><ul><li>(string) Nom</li><li>(string) Prénom</li><li>(string) NAS</li></ul><p><strong>Méthodes publiques</strong></p><ul><li>Constructeur paramétré permettant d&#39;initialiser toutes les propriétés</li><li>ToString() : Afficher l’information de l’employé</li></ul><ol start="2"><li>Créer une classe nommée <strong>ListeEmployes</strong> ayant les propriétés et les méthodes suivantes :</li></ol><p><strong>Attribut privé</strong>:</p><ul><li>(List&lt;Employe&gt;) _employes : Contient la liste des employés</li></ul><p><strong>Propriété public</strong></p><ul><li>(int) NbEmployes : Retourne le nombre d’employés dans la liste</li><li>[int index] : Obtient ou Défini un employé à partir d’une position dans la liste d’employés. L’index ne doit pas être à l’extérieure des plages de valeurs possibles pour la liste d’employés.</li><li>[string nas] : Obtient un employé dans la liste d’employés à partir de son NAS. Le NAS ne peut pas être vide ou nul. Si l’employé n’existe pas, alors on retourne nul.</li></ul><p><strong>Constructeur</strong></p><ul><li>Sans paramètre : Initialise la liste des employés.</li></ul><p><strong>Méthodes publiques :</strong></p><ul><li>Void Ajouter(Employe pEmploye) : Permet d’ajouter un employé à la liste. L’employé ne doit pas être nul.</li><li>Bool Supprimer(Employe pEmploye) : Permet de supprimer un employé de la liste. L’employé ne doit pas être nul. Retourne vrai si la suppression a fonctionné. Faux sinon.</li></ul><ol start="3"><li>Tester l&#39;ajout, la modification et la suppression d&#39;employés dans une liste d&#39;employés (LiseEmploye).</li></ol></details>',6)])])}const b=s(l,[["render",o]]);export{m as __pageData,b as default};
